9		"os"
10		"path/filepath"
11		"sort"
12		"syscall"
13		"time"
14	)
15	
16	// formatMarker identifies the on-disk file format version.
17	const formatMarker = "edgefleet-heartbeats-v1"
18	
19	// onlineWindow is the maximum age of the latest telemetry for a node to be
20	// considered online. Exactly onlineWindow is still online.
21	const onlineWindow = 60 * time.Second
22	
23	// CorruptError means the on-disk data failed parsing or verification. The
24	// store refuses to read or write while corruption is present.
25	type CorruptError struct {
26		Path string
27		Err  error
28	}
29	
30	func (e *CorruptError) Error() string {
31		return fmt.Sprintf("data corruption detected in %s: %v", e.Path, e.Err)
32	}
33	
34	func (e *CorruptError) Unwrap() error { return e.Err }
35	
36	// IsCorrupt reports whether err is (or wraps) a CorruptError.
37	func IsCorrupt(err error) bool {
38		var ce *CorruptError
39		return errors.As(err, &ce)
40	}
41	
42	// nodeFile is the on-disk layout for one node.
43	type nodeFile struct {
44		Format   string      `json:"format"`
45		Checksum string      `json:"checksum"`
46		Records  []Heartbeat `json:"records"`
47	}
48	
49	// Store persists heartbeats as per-node JSON files under a data directory.
50	// Multiple Store instances (in the same or different processes) may safely
51	// access the same directory concurrently: a flock on the directory lock file
52	// serialises writers and lets queries take a shared lock, so a query never
53	// observes a partially written batch.
54	type Store struct {
55		dir      string
56		nodesDir string
57		lockPath string
58	}
59	
60	// OpenStore opens (and if needed creates) a data directory.
61	func OpenStore(dir string) (*Store, error) {
62		if err := os.MkdirAll(dir, 0o755); err != nil {
63			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
64		}
65		nodesDir := filepath.Join(dir, "nodes")
66		if err := os.MkdirAll(nodesDir, 0o755); err != nil {
67			return nil, fmt.Errorf("cannot create nodes directory %s: %w", nodesDir, err)
68		}
69		return &Store{dir: dir, nodesDir: nodesDir, lockPath: filepath.Join(dir, "lock")}, nil
70	}
71	
72	// Dir returns the data directory path.
73	func (s *Store) Dir() string { return s.dir }
74	
75	// nodePath maps a node id to its per-node file. Hex encoding keeps arbitrary
76	// node ids safe as filenames while remaining reversible.
77	func (s *Store) nodePath(nodeID string) string {
78		return filepath.Join(s.nodesDir, hex.EncodeToString([]byte(nodeID))+".json")
79	}
80	
81	// lock acquires the directory lock. Exclusive for writes, shared for reads.
82	// The returned closure releases the lock.
83	func (s *Store) lock(exclusive bool) (func(), error) {
84		f, err := os.OpenFile(s.lockPath, os.O_RDWR|os.O_CREATE, 0o600)
85		if err != nil {
86			return nil, fmt.Errorf("cannot open lock file %s: %w", s.lockPath, err)
87		}
88		how := syscall.LOCK_SH
89		if exclusive {
90			how = syscall.LOCK_EX
91		}
92		if err := syscall.Flock(int(f.Fd()), how); err != nil {
93			f.Close()
94			return nil, fmt.Errorf("cannot acquire data lock: %w", err)
95		}
96		return func() {
97			syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
98			f.Close()
99		}, nil
100	}
101	
102	// checksumRecords returns a stable hash of the records. json.Marshal of a
103	// struct slice is deterministic for a given set of records.
104	func checksumRecords(records []Heartbeat) string {
105		data, _ := json.Marshal(records)
106		sum := sha256.Sum256(data)
107		return hex.EncodeToString(sum[:])
108	}
109	
110	// loadNodeFile reads and verifies the file for one node. A missing file means
111	// the node has no records (returns nil, nil). Any parse, checksum or
112	// structural failure is reported as a CorruptError.
113	func loadNodeFile(path string) (*nodeFile, error) {
114		data, err := os.ReadFile(path)
115		if os.IsNotExist(err) {
116			return nil, nil
117		}
118		if err != nil {
119			return nil, &CorruptError{Path: path, Err: err}
120		}
121		var nf nodeFile
122		if err := json.Unmarshal(data, &nf); err != nil {
123			return nil, &CorruptError{Path: path, Err: fmt.Errorf("invalid JSON: %w", err)}
124		}
125		if nf.Format != formatMarker {
126			return nil, &CorruptError{Path: path, Err: fmt.Errorf("unknown format marker %q", nf.Format)}
127		}
128		if nf.Records == nil {
129			nf.Records = []Heartbeat{}
130		}
131		if err := validateStoredRecords(nf.Records); err != nil {
132			return nil, &CorruptError{Path: path, Err: err}
133		}
134		if got := checksumRecords(nf.Records); got != nf.Checksum {
135			return nil, &CorruptError{Path: path, Err: fmt.Errorf("checksum mismatch: stored %s, computed %s", nf.Checksum, got)}
136		}
137		return &nf, nil
138	}
139	
140	// validateStoredRecords checks the structural invariants of a stored record
141	// set: sorted by ascending seq, no duplicate seq, valid field values.
142	func validateStoredRecords(records []Heartbeat) error {
143		for i, r := range records {
144			if r.NodeID == "" {
145				return fmt.Errorf("record %d: empty node id", i)
146			}
147			if r.Seq <= 0 {
148				return fmt.Errorf("record %d: seq must be a positive integer, got %d", i, r.Seq)
149			}
150			if r.Version == "" {
151				return fmt.Errorf("record %d: empty version", i)
152			}
153			if r.Height < 0 {
154				return fmt.Errorf("record %d: negative height %d", i, r.Height)
155			}
156			if r.Missed < 0 {
157				return fmt.Errorf("record %d: negative missed %d", i, r.Missed)
158			}
159			if r.CollectedAt.IsZero() {
160				return fmt.Errorf("record %d: missing collected_at", i)
161			}
162			if i > 0 && records[i-1].Seq >= r.Seq {
163				return fmt.Errorf("records not sorted by ascending seq at position %d", i)
164			}
165		}
166		return nil
167	}
168	
169	// writeNodeFile persists records atomically: a temp file in the same
170	// directory is fsynced and renamed over the target, so a crash never leaves
171	// a half-written file.
172	func writeNodeFile(path string, records []Heartbeat) error {
173		if records == nil {
174			records = []Heartbeat{}
175		}
176		nf := nodeFile{
177			Format:   formatMarker,
178			Checksum: checksumRecords(records),
179			Records:  records,
180		}
181		data, err := json.MarshalIndent(nf, "", "  ")
182		if err != nil {
183			return err
184		}
185		return writeFileAtomic(path, data)
186	}
187	
188	func writeFileAtomic(path string, data []byte) error {
189		dir := filepath.Dir(path)
190		tmp, err := os.CreateTemp(dir, ".tmp-*")
191		if err != nil {
192			return err
193		}
194		tmpName := tmp.Name()
195		if _, err := tmp.Write(data); err != nil {
196			tmp.Close()
197			os.Remove(tmpName)
198			return err
199		}
200		if err := tmp.Sync(); err != nil {
201			tmp.Close()
202			os.Remove(tmpName)
203			return err
204		}
205		if err := tmp.Close(); err != nil {
206			os.Remove(tmpName)
207			return err
208		}
209		if err := os.Rename(tmpName, path); err != nil {
210			os.Remove(tmpName)
211			return err
212		}
213		// Best-effort fsync of the directory so the rename itself survives.
214		if d, err := os.Open(dir); err == nil {
215			d.Sync()
216			d.Close()
217		}
218		return nil
219	}
220	
221	// Submit persists a batch of heartbeats. The whole batch is validated and
222	// checked for duplicates/conflicts against stored data (and within the batch)
223	// before anything is written: a single invalid or conflicting record fails
224	// the batch with no changes. Duplicates are counted, not written. A
225	// successful return means the batch was durably persisted; a persistence
226	// failure is reported and previously queryable data is left intact.
227	func (s *Store) Submit(records []Heartbeat, receiveTime time.Time) (newCount, dupCount int, err error) {
228		if len(records) == 0 {
229			return 0, 0, fmt.Errorf("no heartbeat records provided")
230		}
231		for _, r := range records {
232			if err := ValidateHeartbeat(r, receiveTime); err != nil {
233				return 0, 0, fmt.Errorf("invalid heartbeat for node %q seq %d: %w", r.NodeID, r.Seq, err)
234			}
235		}
236	
237		unlock, err := s.lock(true)
238		if err != nil {
239			return 0, 0, err
240		}
241		defer unlock()
242	
243		// Deduplicate within the batch: same node+seq with equal fields counts
244		// as a duplicate; same node+seq with differing content is a conflict.
245		merged := make(map[string][]Heartbeat)
246		for _, r := range records {
247			list := merged[r.NodeID]
248			found := -1
249			for i, e := range list {
250				if e.Seq == r.Seq {
251					found = i
252					break
253				}
254			}
255			if found >= 0 {
256				if !list[found].Equal(r) {
257					return 0, 0, fmt.Errorf("conflicting records for node %q seq %d in batch: content differs", r.NodeID, r.Seq)
258				}
259				dupCount++
260				continue
261			}
262			merged[r.NodeID] = append(list, r)
263		}
264	
265		// Merge with stored data per node, collecting new file contents.
266		type update struct {
267			path    string
268			records []Heartbeat
269		}
270		var updates []update
271		for nodeID, batch := range merged {
272			path := s.nodePath(nodeID)
273			nf, err := loadNodeFile(path)
274			if err != nil {
275				return 0, 0, err
276			}
277			existing := []Heartbeat{}
278			if nf != nil {
279				existing = nf.Records
280			}
281			for _, r := range batch {
282				found := -1
283				for i, e := range existing {
284					if e.Seq == r.Seq {
285						found = i
286						break
287					}
288				}
289				if found >= 0 {
290					if !existing[found].Equal(r) {
291						return 0, 0, fmt.Errorf("conflicting record for node %q seq %d: content differs from stored record", nodeID, r.Seq)
292					}
293					dupCount++
294					continue
295				}
296				existing = append(existing, r)
297				newCount++
298			}
299			sort.Slice(existing, func(i, j int) bool { return existing[i].Seq < existing[j].Seq })
300			updates = append(updates, update{path: path, records: existing})
301		}
302	
303		// Persist. All updates are appends to previously verified data, so a
304		// failure here leaves every previously queryable record intact.
305		for _, u := range updates {
306			if err := writeNodeFile(u.path, u.records); err != nil {
307				return 0, 0, fmt.Errorf("failed to persist heartbeat batch: %w", err)
308			}
309		}
310		return newCount, dupCount, nil
311	}
312	
313	// HealthResult is the health judgement for one node based on real telemetry.
314	type HealthResult struct {
315		NodeID      string
316		Status      string // "online", "offline", "notelemetry"
317		Seq         int64
318		CollectedAt time.Time
319		Version     string
320		Height      int64
321		Missed      int64 // cumulative missed duties at the latest heartbeat
322		Findings    []string
323	
324		// Baseline-relative missed duties, populated only by HealthSince.
325		// BaselineSeq is the seq of the heartbeat the query was anchored to;
326		// BaselineMissed is the cumulative count at that heartbeat. When
327		// NewMissedKnown is false the cumulative counter went backwards
328		// somewhere between the baseline and the latest record, so the number of
329		// newly missed duties cannot be derived; Findings then reports the
330		// rollback. Missed always remains the latest cumulative count.
331		BaselineSeq    int64
332		BaselineMissed int64
333		NewMissed      int64
334		NewMissedKnown bool
335	}
336	
337	// rollbackFinding warns that the cumulative missed-duty counter decreased
338	// between two adjacent saved heartbeats (typically a node counter reset),
339	// which makes the endpoint difference unusable as the new-miss count.
340	const rollbackFinding = "累计漏签数回退"
341	
342	// Health judges a node from its latest telemetry (the record with the
343	// greatest seq). A node with no heartbeats returns Status "notelemetry". A
344	// query time earlier than the record's collection time is an error. Online
345	// status uses collection age against the query time: at most 60s is online
346	// (exactly 60s still online). Version skew and missed-duty rules follow the
347	// existing Evaluate rules.
348	func (s *Store) Health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int) (HealthResult, error) {
349		return s.health(nodeID, at, expectedVersion, toleratedMisses, 0, false)
350	}
351	
352	// HealthSince judges a node the same way Health does, but the missed-duty
353	// alarm is measured against a user-supplied baseline heartbeat instead of the
354	// cumulative counter alone. baselineSeq must be the seq (> 0) of a record
355	// already saved for the node: the latest heartbeat stays the record with the
356	// greatest seq, and new missed duties are the latest cumulative count minus
357	// the count at the baseline record. Only a strict excess over
358	// toleratedMisses alarms; equality does not.
359	//
360	// The baseline affects this query only: stored history is never modified.
361	// Seqs between the baseline and the latest may have gaps. If the cumulative
362	// count decreases between any two adjacent saved records in that interval the
363	// new count is reported as unknown (NewMissedKnown == false) and a rollback
364	// finding is emitted, even if the latest count later climbs back past the
365	// baseline; decreases before the baseline are irrelevant. A node without
366	// telemetry, an unknown baseline seq, or a baseline newer than the latest
367	// record is an error — no other record is substituted and the baseline count
368	// is never assumed to be zero.
369	func (s *Store) HealthSince(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64) (HealthResult, error) {
370		if baselineSeq <= 0 {
371			return HealthResult{}, fmt.Errorf("--missed-since-seq must be a positive integer, got %d", baselineSeq)
372		}
373		return s.health(nodeID, at, expectedVersion, toleratedMisses, baselineSeq, true)
374	}
375	
376	func (s *Store) health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64, useBaseline bool) (HealthResult, error) {
377		unlock, err := s.lock(false)
378		if err != nil {
379			return HealthResult{}, err
380		}
381		defer unlock()
382	
383		nf, err := loadNodeFile(s.nodePath(nodeID))
384		if err != nil {
385			return HealthResult{}, err
386		}
387		if nf == nil || len(nf.Records) == 0 {
388			if useBaseline {
389				return HealthResult{}, fmt.Errorf("node %q has no heartbeats; cannot use --missed-since-seq=%d as baseline", nodeID, baselineSeq)
390			}
391			return HealthResult{NodeID: nodeID, Status: "notelemetry", Findings: []string{"无遥测"}}, nil
392		}
393	
394		records := nf.Records // ascending seq, unique
395		latest := records[len(records)-1]
396	
397		if useBaseline {
398			if baselineSeq > latest.Seq {
399				return HealthResult{}, fmt.Errorf("--missed-since-seq=%d is newer than the latest heartbeat seq %d for node %q", baselineSeq, latest.Seq, nodeID)
400			}
401		}
402	
403		if at.Before(latest.CollectedAt) {
404			return HealthResult{}, fmt.Errorf("query time %s is earlier than collection time %s for node %q",
405				at.Format(time.RFC3339), latest.CollectedAt.Format(time.RFC3339), nodeID)
406		}
407	
408		age := at.Sub(latest.CollectedAt)
409		online := age <= onlineWindow
410	
411		findings := []string{}
412		if !online {
413			findings = append(findings, "offline")
414		}
415		if latest.Version != expectedVersion {
416			findings = append(findings, "version skew: "+latest.Version+" != "+expectedVersion)
417		}
418	
419		result := HealthResult{
420			NodeID:      nodeID,
421			Status:      "online",
422			Seq:         latest.Seq,
423			CollectedAt: latest.CollectedAt,
424			Version:     latest.Version,
425			Height:      latest.Height,
426			Missed:      latest.Missed,
427		}
428		if !online {
429			result.Status = "offline"
430		}
431	
432		if !useBaseline {
433			// Cumulative judgement: the current counter must strictly exceed the
434			// tolerance (mirrors Evaluate for callers that do not use a baseline).
435			node := Node{
436				ID:      nodeID,
437				Version: latest.Version,
438				Height:  latest.Height,
439				Missed:  int(latest.Missed),
440				Online:  online,
441			}
442			result.Findings = Evaluate(node, expectedVersion, toleratedMisses).Findings
443			return result, nil
444		}
445	
446		baselineIdx := -1
447		for i, r := range records {
448			if r.Seq == baselineSeq {
449				baselineIdx = i
450				break
451			}
452		}
453		if baselineIdx < 0 {
454			return HealthResult{}, fmt.Errorf("no saved heartbeat with seq %d for node %q; cannot use it as --missed-since-seq baseline", baselineSeq, nodeID)
455		}
456		baseline := records[baselineIdx]
457		result.BaselineSeq = baseline.Seq
458		result.BaselineMissed = baseline.Missed
459	
460		// Walk only saved records from the baseline up to the latest. Records are
461		// stored ascending by seq and seqs may legitimately have gaps, so any
462		// decrease between two adjacent saved records in this interval proves the
463		// cumulative counter reset somewhere in it; the endpoint difference alone
464		// must not be trusted even if the final count recovers.
465		rolledBack := false
466		for i := baselineIdx + 1; i < len(records); i++ {
467			if records[i].Missed < records[i-1].Missed {
468				rolledBack = true
469				break
470			}
471		}
472		if rolledBack {
473			result.NewMissedKnown = false
474			findings = append(findings, rollbackFinding)
475		} else {
476			result.NewMissedKnown = true
477			// No decrease was observed, so cumulative counts cannot have wrapped
478			// backwards within int64 range; the difference stays exact.
479			result.NewMissed = latest.Missed - baseline.Missed
480			if result.NewMissed > int64(toleratedMisses) {
481				findings = append(findings, "missed duties above tolerance")
482			}
483		}
484		result.Findings = findings
485		return result, nil
486	}
487	
488	// History returns all heartbeats for a node in ascending seq order, without
489	// duplicates. A node with no records returns an empty slice.
490	func (s *Store) History(nodeID string) ([]Heartbeat, error) {
491		unlock, err := s.lock(false)
492		if err != nil {
493			return nil, err
494		}
495		defer unlock()
496	
497		nf, err := loadNodeFile(s.nodePath(nodeID))
498		if err != nil {
499			return nil, err
500		}
501		if nf == nil {
502			return []Heartbeat{}, nil
503		}
504		return nf.Records, nil
505	}
506

