363		if !r.NewMissedKnown || r.NewMissed != 2 {
364			t.Errorf("after reopen: known=%v new=%d, want true/2", r.NewMissedKnown, r.NewMissed)
365		}
366		cum, err := store2.Health("n1", receive, "1.0", 2)
367		if err != nil {
368			t.Fatal(err)
369		}
370		if cum.BaselineSeq != 0 || cum.NewMissedKnown {
371			t.Errorf("plain Health must leave baseline fields zero: %+v", cum)
372		}
373		if !hasFinding(cum.Findings, "missed duties above tolerance") {
374			t.Errorf("plain Health must keep judging cumulative counts: %v", cum.Findings)
375		}
376	}
