14	var testBase = time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC)
15	
16	func hb(node string, seq int64, collected time.Time, version string, height, missed int64) Heartbeat {
17		return Heartbeat{
18			NodeID:      node,
19			Seq:         seq,
20			CollectedAt: collected,
21			Version:     version,
22			Height:      height,
23			Missed:      missed,
24		}
