26	
27	func TestParseHeartbeatsValid(t *testing.T) {
28		input := `[
29		  {"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0.0","height":100,"missed":0},
30		  {"node":"val-2","seq":2,"collected_at":"2026-10-01T20:00:00+08:00","version":"1.0.0","height":101,"missed":1}
31		]`
32		records, err := ParseHeartbeats([]byte(input), testBase)
33		if err != nil {
